import { useRef, useState } from 'react';
import { Minus, Plus, RotateCcw, Save, Users } from 'lucide-react';
import { organizationId, backend } from '../lib/backend';

export function AttendancePage({userId}:{userId:string}){const[n,setN]=useState(0);const[r,setR]=useState(0);const[history,setHistory]=useState<('new'|'returning')[]>([]);const[service,setService]=useState('Sabbath Service');const[busy,setBusy]=useState(false);const saving=useRef(false);const pending=useRef<{id:string;organization_id:string;service_name:string;service_date:string;new_visitors:number;returning_visitors:number;created_by:string}|null>(null);function add(type:'new'|'returning'){if(saving.current||pending.current)return;type==='new'?setN(x=>x+1):setR(x=>x+1);setHistory(x=>[...x,type])}function undo(){if(saving.current||pending.current)return;const last=history.at(-1);if(!last)return;last==='new'?setN(x=>Math.max(0,x-1)):setR(x=>Math.max(0,x-1));setHistory(x=>x.slice(0,-1))}async function save(){if(saving.current)return;if(!service.trim()||n+r===0)return alert('Enter a service name and at least one attendee.');saving.current=true;setBusy(true);pending.current||={id:crypto.randomUUID(),organization_id:organizationId,service_name:service.trim(),service_date:new Date().toISOString().slice(0,10),new_visitors:n,returning_visitors:r,created_by:userId};try{const{error}=await backend.from('attendance_sessions').upsert(pending.current,{onConflict:'id',ignoreDuplicates:true});if(error)throw error;const saved=pending.current;setN(x=>Math.max(0,x-saved.new_visitors));setR(x=>Math.max(0,x-saved.returning_visitors));setHistory([]);pending.current=null;alert('Service saved.')}catch(error){alert((error as {message?:string})?.message||'Unable to save. Retry to confirm this service without duplicating it.')}finally{saving.current=false;setBusy(false)}}return <><article className="panel service-bar"><label>Service name<input disabled={busy||Boolean(pending.current)} value={service} onChange={e=>setService(e.target.value)}/></label><div><span>Today</span><strong>{new Date().toLocaleDateString()}</strong></div></article><section className="counter-grid"><article className="counter new"><Users/><span>New visitors</span><strong key={n}>{n}</strong><button disabled={busy||Boolean(pending.current)} onClick={()=>add('new')}><Plus/> New visitor</button><button className="counter-remove" disabled={busy||Boolean(pending.current)} onClick={()=>setN(x=>Math.max(0,x-1))}><Minus/> Remove</button></article><article className="counter returning"><Users/><span>Returning visitors</span><strong key={r}>{r}</strong><button disabled={busy||Boolean(pending.current)} onClick={()=>add('returning')}><Plus/> Returning visitor</button><button className="counter-remove" disabled={busy||Boolean(pending.current)} onClick={()=>setR(x=>Math.max(0,x-1))}><Minus/> Remove</button></article><article className="counter total"><Users/><span>Total attendance</span><strong key={n+r}>{n+r}</strong><p>New {n} · Returning {r}</p></article></section><article className="panel action-row"><button className="secondary" disabled={busy||Boolean(pending.current)} onClick={undo}><RotateCcw/> Undo last</button><button className="primary" disabled={busy} onClick={save}><Save/> {busy?'Saving…':pending.current?'Retry save':'Save service'}</button></article></>}
